import json,sys
d=json.load(sys.stdin)
def walk(x,depth=0):
    items = x if isinstance(x,list) else [x]
    for it in items:
        if not isinstance(it,dict): continue
        print('='*70)
        for k in ('id','name','status','owner','milestone','pinned_commit','pin_commit'):
            if k in it: print(k,':',it[k])
        s=it.get('summary') or ''
        print('--- summary ---'); print(s[:3000])
        for c in (it.get('children') or []): walk(c,depth+1)
walk(d.get('items') or d)
" 2>&1 | head -80

