import json,sys
d=json.load(sys.stdin)
def flat(x,out):
    for it in (x if isinstance(x,list) else [x]):
        if not isinstance(it,dict): continue
        out.append(it)
        for c in (it.get('children') or []): flat(c,out)
out=[]
flat(d.get('items') or d,out)
for it in out:
    if it.get('id') in ('AJCR.w5-av','AJCR.w5-av.t3','AJCR.w5-av.t5','AJCR.w5-av.s1','AJCR.w5-av.s3','AJCR.w5-av.p1'):
